"import json
from drain3 import TemplateMiner
from drain3.template_miner_config import TemplateMinerConfig

class UniversalParser:
    def __init__(self):
        config = TemplateMinerConfig()
        config.load("") # Load default config
        self.template_miner = TemplateMiner(config=config)

    def parse(self, log_entry: str, format_type: str) -> dict:
        result = {
            "original_log": log_entry,
            "format_detected": format_type,
            "parsed_fields": {}
        }

        if format_type == "json":
            result["parsed_fields"] = json.loads(log_entry)

        elif format_type == "syslog":
            # Very basic syslog parsing for demo
            parts = log_entry.split(maxsplit=4)
            if len(parts) >= 5:
                result["parsed_fields"] = {
                    "timestamp": f"{parts[0]} {parts[1]} {parts[2]}",
                    "host": parts[3],
                    "message": parts[4]
                }

        elif format_type == "unstructured":
            # Use Drain3 to extract template and variables
            miner_result = self.template_miner.add_log_message(log_entry)
            result["parsed_fields"] = {
                "template_id": miner_result["cluster_id"],
                "template": miner_result["template_mined"],
                "extracted_parameters": self.template_miner.extract_parameters(
                    miner_result["template_mined"], log_entry, exact_matching=False
                )
            }

        return result

    def get_templates(self):
        return [cluster.__dict__ for cluster in self.template_miner.drain.clusters]
