"import pandas as pd

class Normalizer:
    def __init__(self):
        # Mapping of common timestamp fields to a standard 'timestamp' field
        self.timestamp_fields = ['time', 'date', 'ts', '@timestamp', 'datetime']
        self.severity_fields = ['level', 'severity', 'log_level']

    def normalize(self, parsed_data: dict) -> dict:
        fields = parsed_data.get("parsed_fields", {})
        if not isinstance(fields, dict):
            return parsed_data

        normalized_fields = {}

        for key, value in fields.items():
            key_lower = key.lower()

            # Normalize Timestamp
            if key_lower in self.timestamp_fields or key_lower == 'timestamp':
                try:
                    # Convert to ISO 8601 string
                    ts = pd.to_datetime(value)
                    normalized_fields['standard_timestamp'] = ts.isoformat()
                except Exception:
                    normalized_fields['standard_timestamp'] = str(value)
                continue

            # Normalize Severity
            if key_lower in self.severity_fields:
                normalized_fields['standard_severity'] = str(value).upper()
                continue

            # Keep other fields as is
            normalized_fields[key] = value

        parsed_data["normalized_fields"] = normalized_fields
        return parsed_data
