"document.getElementById('process-btn').addEventListener('click', async () => {
    const inputArea = document.getElementById('log-input');
    const outputArea = document.getElementById('log-output');
    const btn = document.getElementById('process-btn');

    const rawText = inputArea.value.trim();
    if (!rawText) {
        outputArea.textContent = 'Please enter some logs to process.';
        outputArea.style.color = '#fca5a5';
        return;
    }

    // Split by lines, remove empty lines
    const logs = rawText.split('\n').filter(line => line.trim().length > 0);

    btn.textContent = 'Processing...';
    btn.disabled = true;
    outputArea.style.color = '#a7f3d0';

    try {
        const response = await fetch('/api/logs/ingest', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ logs })
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();

        // Pretty print JSON
        outputArea.textContent = JSON.stringify(data.processed_logs, null, 2);

        // Add a nice little success animation
        outputArea.style.opacity = 0;
        setTimeout(() => {
            outputArea.style.transition = 'opacity 0.5s ease';
            outputArea.style.opacity = 1;
        }, 50);

    } catch (error) {
        outputArea.textContent = `Error processing logs:\n${error.message}`;
        outputArea.style.color = '#fca5a5';
    } finally {
        btn.textContent = 'Process Logs';
        btn.disabled = false;
    }
});"
